// Copies docs/openapi.yaml into lib/src/routes/openapi_document.dart, so that
// the server can serve it without the file. Run from unpub/ after changing
// the document: dart run tool/embed_openapi.dart
import 'dart:io';

const source = '../docs/openapi.yaml';
const target = 'lib/src/routes/openapi_document.dart';

String embedded(String document) {
  if (document.contains("'''")) {
    throw const FormatException("the document must not contain '''");
  }
  return '// Generated by tool/embed_openapi.dart from docs/openapi.yaml. '
      'Do not edit.\n\n'
      '/// The OpenAPI description of the web API, served at\n'
      '/// `/webapi/openapi.yaml`.\n'
      "const openApiDocument = r'''\n$document''';\n";
}

void main() {
  File(target).writeAsStringSync(embedded(File(source).readAsStringSync()));
  stdout.writeln('wrote $target');
}
